<script setup>
import { ref,reactive,computed,onMounted,onUnmounted } from 'vue';import { useRoute } from 'vue-router';import { ArrowLeft,Download,Upload,CheckCircle2,Clock,FileCheck,BedDouble,ArrowRight,Plus,RefreshCw } from 'lucide-vue-next';import { api,session,download } from '../lib/api';import { currency,dateText,label } from '../lib/format';import { notify } from '../lib/ui';import StatusBadge from '../components/StatusBadge.vue';import StatePanel from '../components/StatePanel.vue';import AppModal from '../components/AppModal.vue';
const route=useRoute(),b=ref(null),loading=ref(true),error=ref(''),busy=ref(false),modal=ref(''),modalError=ref(''),submitted=ref(false),now=ref(Date.now());const isAdmin=computed(()=>session.user?.role==='admin');const reason=ref('');const payment=reactive({amount:'',payment_method:'bank_transfer',reference_number:'',file:null});const document=reactive({document_type:'national_id',file:null});const charge=reactive({charge_name:'',quantity:1,unit_price:'',note:''});
const active=computed(()=>b.value&&['pending','confirmed','checked_in'].includes(b.value.booking_status));const pendingSum=computed(()=>b.value?.payments.filter(p=>p.payment_status==='pending').reduce((s,p)=>s+Number(p.amount),0)||0);const payable=computed(()=>Math.max(0,Number(b.value?.financial.balance||0)-pendingSum.value));const timeLeft=computed(()=>{if(!b.value?.expires_at||b.value.booking_status!=='pending')return '';const seconds=Math.max(0,Math.floor((Date.parse(b.value.expires_at.replace(' ','T')+'+07:00')-now.value)/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;});let timer;
async function load(){loading.value=true;error.value='';try{b.value=(await api('/bookings/'+route.params.id)).data;}catch(e){error.value=e.message;}finally{loading.value=false;}}
function open(kind){modal.value=kind;modalError.value='';reason.value='';payment.amount=payable.value.toFixed(2);payment.file=null;payment.reference_number='';payment.payment_method=isAdmin.value?'cash':'bank_transfer';document.file=null;charge.charge_name='';charge.unit_price='';charge.quantity=1;}
async function action(){busy.value=true;modalError.value='';try{
 const id=b.value.booking_id;
 if(modal.value==='payment'){
  const data={amount:payment.amount,payment_method:payment.payment_method};if(payment.reference_number.trim())data.reference_number=payment.reference_number.trim();
  if(payment.payment_method==='cash'){const p=(await api(`/bookings/${id}/payments`,{method:'POST',body:data})).data;await api(`/admin/payments/${p.payment_id}/verify`,{method:'PATCH',body:{status:'successful'}});notify('บันทึกรับเงินสดสำเร็จ');}
  else{if(!payment.file)throw Error('กรุณาแนบหลักฐาน');const form=new FormData();Object.entries(data).forEach(([key,value])=>form.set(key,value));form.set('file',payment.file);await api(`/bookings/${id}/payments`,{method:'POST',body:form});submitted.value=true;notify('ส่งหลักฐานแล้ว รอเจ้าหน้าที่ตรวจสอบ');}
 }else if(modal.value==='document'){if(!document.file)throw Error('กรุณาแนบเอกสาร');const form=new FormData();form.set('document_type',document.document_type);form.set('file',document.file);await api(`/bookings/${id}/identity-documents`,{method:'POST',body:form});notify('ส่งเอกสารแล้ว');}
 else if(modal.value==='cancel'){await api(`/bookings/${id}/cancel`,{method:'PATCH',body:{reason:reason.value}});notify('ยกเลิกการจองแล้ว');}
 else if(modal.value==='check-in'||modal.value==='check-out'){await api(`/admin/bookings/${id}/${modal.value}`,{method:'POST',body:{}});notify('บันทึกการเข้าพักเรียบร้อย');}
 else if(modal.value==='no-show'){await api(`/admin/bookings/${id}/no-show`,{method:'PATCH',body:{}});notify('บันทึก no-show แล้ว');}
 else if(modal.value==='charge'){await api(`/admin/stays/${b.value.stay.stay_id}/additional-charges`,{method:'POST',body:{charge_name:charge.charge_name,quantity:charge.quantity,unit_price:charge.unit_price,note:charge.note}});notify('เพิ่มค่าใช้จ่ายแล้ว');}
 modal.value='';await load();
}catch(e){modalError.value=e.message;await load();}finally{busy.value=false;}}
async function saveFile(path,name){try{await download(path,name);}catch(e){notify(e.message,'error');}}
function chooseFile(e,target){const file=e.target.files[0];if(file&&file.size>5*1024*1024){modalError.value='ไฟล์ต้องไม่เกิน 5 MB';e.target.value='';return;}target.file=file;modalError.value='';}
onMounted(()=>{load();timer=setInterval(()=>now.value=Date.now(),1000);});onUnmounted(()=>clearInterval(timer));
const bank={name:import.meta.env.VITE_BANK_NAME,account:import.meta.env.VITE_BANK_ACCOUNT,owner:import.meta.env.VITE_BANK_OWNER,promptpay:import.meta.env.VITE_PROMPTPAY_ID};
</script>
<template><section class="container section compact"><RouterLink :to="isAdmin?'/admin/bookings':'/my-bookings'" class="text-link"><ArrowLeft :size="17"/> กลับไปการจอง</RouterLink><StatePanel :loading="loading" :error="error" @retry="load"/><template v-if="b&&!loading"><div v-if="route.query.created||submitted" class="alert success"><CheckCircle2 :size="22"/><span><strong>{{ submitted?'ส่งหลักฐานเรียบร้อย':'สร้างการจองเรียบร้อย' }}</strong><br/>{{ submitted?'เจ้าหน้าที่จะตรวจสอบหลักฐาน การชำระเงินยังอยู่ระหว่างตรวจสอบ':'โปรดส่งหลักฐานและเอกสารยืนยันเพื่อให้โรงแรมตรวจสอบ' }}</span></div><div class="page-heading"><div><p class="eyebrow">RESERVATION DETAILS</p><h1>รายละเอียดการจอง</h1><p class="muted">{{ b.booking_number }}</p></div><div class="button-row"><StatusBadge :value="b.booking_status"/><button class="icon-btn" aria-label="โหลดข้อมูลใหม่" @click="load"><RefreshCw :size="18"/></button></div></div><div v-if="timeLeft" class="alert info"><Clock :size="18"/> เวลาถือห้องคงเหลือ {{ timeLeft }} นาที · การส่งหลักฐานยังไม่ใช่การยืนยัน กรุณาติดต่อโรงแรมให้ตรวจภายในเวลานี้</div><div class="booking-layout"><div class="stack"><section class="panel"><h2>การเข้าพักของคุณ</h2><div class="summary-dates"><div><small>วันเข้าพัก</small><strong>{{ dateText(b.check_in_date) }}</strong></div><ArrowRight :size="20"/><div><small>วันเช็กเอาต์</small><strong>{{ dateText(b.check_out_date) }}</strong></div><span class="badge active">{{ b.nights }} คืน</span></div><p class="muted">{{ b.first_name }} {{ b.last_name }} · {{ b.adult_count }} ผู้ใหญ่ · {{ b.child_count }} เด็ก</p><div v-for="room in b.rooms" :key="room.room_id" class="summary-line"><div><strong>{{ room.type_name }} · ห้อง {{ room.room_number }}</strong><small>{{ room.adult_count }} ผู้ใหญ่ · {{ room.child_count }} เด็ก</small></div><strong>{{ currency(room.room_total) }}</strong></div><p v-if="b.special_request" class="muted">คำขอเพิ่มเติม: {{ b.special_request }}</p><div v-if="isAdmin" class="button-row"><button v-if="b.booking_status==='confirmed'" class="btn primary" @click="open('check-in')">Check-in</button><button v-if="b.booking_status==='checked_in'" class="btn primary" @click="open('check-out')">Check-out</button><button v-if="b.booking_status==='checked_in'&&b.stay" class="btn outline" @click="open('charge')"><Plus :size="16"/> ค่าใช้จ่ายเพิ่มเติม</button><button v-if="b.booking_status==='confirmed'" class="btn outline" @click="open('no-show')">บันทึกไม่มาเข้าพัก</button></div></section><section class="panel"><div class="section-heading"><div><h2>การชำระเงิน</h2><p class="muted">หลักฐานจะผ่านการตรวจสอบโดยเจ้าหน้าที่</p></div><button v-if="active&&payable>0" class="btn outline" @click="open('payment')"><Upload :size="16"/> {{ isAdmin?'บันทึกชำระเงิน':'ส่งหลักฐาน' }}</button></div><div v-if="!b.payments.length" class="empty-inline">ยังไม่มีรายการชำระเงิน</div><div v-for="p in b.payments" :key="p.payment_id" class="summary-line"><div><strong>{{ currency(p.amount) }}</strong><small>{{ label(p.payment_method) }} · {{ p.payment_number }}</small></div><div class="button-row"><StatusBadge :value="p.payment_status"/><button v-if="p.payment_method!=='cash'" class="icon-btn" aria-label="ดาวน์โหลดหลักฐาน" @click="saveFile('/payments/'+p.payment_id+'/proof','payment-proof')"><Download :size="17"/></button></div></div><div v-for="rc in b.receipts" :key="rc.receipt_id" class="receipt-row"><div><strong>ใบเสร็จ {{ rc.receipt_number }}</strong><small>{{ currency(rc.net_amount) }}</small></div><button class="btn tiny outline" @click="saveFile('/receipts/'+rc.receipt_id+'/pdf',rc.receipt_number+'.pdf')"><Download :size="15"/> PDF</button></div><RouterLink v-if="isAdmin" to="/admin/payments" class="text-link">ไปตรวจรายการชำระเงิน <ArrowRight :size="15"/></RouterLink></section><section class="panel"><div class="section-heading"><div><h2>เอกสารยืนยันตัวตน</h2><p class="muted">ต้องมีเอกสารที่อนุมัติก่อนเข้าพัก</p></div><button v-if="['pending','confirmed'].includes(b.booking_status)" class="btn outline" @click="open('document')"><Upload :size="16"/> ส่งเอกสาร</button></div><div v-if="!b.documents.length" class="empty-inline">ยังไม่ได้ส่งเอกสาร</div><div v-for="d in b.documents" :key="d.document_id" class="summary-line"><div><strong>{{ label(d.document_type) }}</strong><small v-if="d.review_note">{{ d.review_note }}</small></div><div class="button-row"><StatusBadge :value="d.document_status"/><button class="icon-btn" aria-label="ดาวน์โหลดเอกสาร" @click="saveFile('/identity-documents/'+d.document_id+'/file','identity-document')"><Download :size="17"/></button></div></div><RouterLink v-if="isAdmin" to="/admin/documents" class="text-link">ไปตรวจเอกสาร <ArrowRight :size="15"/></RouterLink></section><section v-if="b.charges?.length" class="panel"><h2>ค่าใช้จ่ายเพิ่มเติม</h2><div v-for="c in b.charges" :key="c.charge_id" class="summary-line"><span>{{ c.charge_name }} × {{ c.quantity }}</span><strong>{{ currency(c.total_amount) }}</strong></div></section></div><aside class="panel booking-summary"><p class="eyebrow">PAYMENT SUMMARY</p><h3>สรุปยอดการจอง</h3><div class="summary-line"><span>ค่าห้องพัก</span><strong>{{ currency(b.financial.room_amount) }}</strong></div><div class="summary-line"><span>ค่าใช้จ่ายเพิ่มเติม</span><strong>{{ currency(b.financial.additional_amount) }}</strong></div><div class="summary-line"><span>ยอดรวมทั้งหมด</span><strong>{{ currency(b.financial.grand_total) }}</strong></div><div class="summary-line"><span>ชำระสำเร็จแล้ว</span><strong class="text-green">{{ currency(b.financial.paid_amount) }}</strong></div><div class="summary-total"><span>ยอดคงเหลือ</span><strong>{{ currency(b.financial.balance) }}</strong></div><p v-if="pendingSum" class="field-help">รอตรวจสอบ {{ currency(pendingSum) }}</p><button v-if="active&&payable>0" class="btn primary full" @click="open('payment')">{{ isAdmin?'บันทึกรับเงิน':'ส่งหลักฐานชำระเงิน' }}</button><small>การส่งสลิปยังไม่ถือว่าชำระสำเร็จ<br/>รอเจ้าหน้าที่ตรวจสอบสถานะ</small><button v-if="['pending','confirmed'].includes(b.booking_status)" class="text-danger cancel-link" @click="open('cancel')">ยกเลิกการจองนี้</button></aside></div></template><AppModal v-if="modal" :title="({payment:'ชำระเงิน',document:'ส่งเอกสารยืนยัน',cancel:'ยกเลิกการจอง','check-in':'ยืนยัน Check-in','check-out':'ยืนยัน Check-out',charge:'ค่าใช้จ่ายเพิ่มเติม','no-show':'บันทึกไม่มาเข้าพัก'})[modal]" @close="!busy&&(modal='')"><form @submit.prevent="action"><div v-if="modalError" class="alert danger" role="alert">{{ modalError }}</div><template v-if="modal==='payment'"><label>จำนวนเงิน<input v-model="payment.amount" type="number" min="0.01" step="0.01" :max="payable" required/></label><label>วิธีชำระเงิน<select v-model="payment.payment_method"><option v-if="isAdmin" value="cash">เงินสด</option><option value="bank_transfer">โอนธนาคาร</option><option value="promptpay">พร้อมเพย์</option></select></label><template v-if="payment.payment_method!=='cash'"><div class="alert info" v-if="payment.payment_method==='bank_transfer'&&bank.account"><span>{{ bank.name }} · {{ bank.account }}<br/>ชื่อบัญชี {{ bank.owner }}</span></div><div class="alert info" v-else-if="payment.payment_method==='promptpay'&&bank.promptpay">พร้อมเพย์ {{ bank.promptpay }}</div><div class="alert info" v-else>โรงแรมยังไม่ได้ระบุบัญชีรับเงิน กรุณาติดต่อโรงแรมก่อนโอน</div><label>เลขอ้างอิง <small>(ไม่บังคับ)</small><input v-model="payment.reference_number" maxlength="100"/></label><label>หลักฐานการชำระเงิน<input type="file" accept="image/png,image/jpeg,application/pdf" @change="chooseFile($event,payment)" required/></label><small>PNG, JPEG หรือ PDF ไม่เกิน 5 MB</small></template><div v-else class="alert info">กดยืนยันเมื่อรับเงินสดแล้ว ระบบจะบันทึกรายการและออกใบเสร็จ</div></template><template v-else-if="modal==='document'"><label>ชนิดเอกสาร<select v-model="document.document_type"><option value="national_id">บัตรประชาชน</option><option value="passport">หนังสือเดินทาง</option></select></label><label>ไฟล์เอกสาร<input type="file" accept="image/png,image/jpeg,application/pdf" @change="chooseFile($event,document)" required/></label><p class="field-help">ไฟล์ไม่เกิน 5 MB · เปิดดูได้เฉพาะเจ้าของการจองและเจ้าหน้าที่</p></template><template v-else-if="modal==='charge'"><label>รายการ<input v-model="charge.charge_name" required maxlength="150"/></label><div class="form-grid"><label>จำนวน<input type="number" v-model.number="charge.quantity" min="1" max="10000" required/></label><label>ราคาต่อหน่วย<input type="number" v-model="charge.unit_price" min="0" step="0.01" required/></label></div><label>หมายเหตุ<input v-model="charge.note" maxlength="1000"/></label></template><template v-else-if="modal==='cancel'"><p>ยืนยันการยกเลิก {{ b.booking_number }}? หากมีเงินที่ชำระแล้ว ต้องให้โรงแรมบันทึกคืนเงินก่อน</p><label>เหตุผล<textarea v-model="reason" maxlength="1000" rows="3"></textarea></label></template><template v-else><p>ยืนยันดำเนินการกับการจอง {{ b.booking_number }}?</p><p class="field-help" v-if="modal==='check-in'">ต้องชำระค่าห้องครบ มีเอกสาร approved และห้องพร้อมใช้งาน</p><p class="field-help" v-if="modal==='check-out'">ยอดคงเหลือต้องเป็นศูนย์ ห้องจะเปลี่ยนเป็นกำลังทำความสะอาด</p><p class="field-help" v-if="modal==='no-show'">ใช้ได้เมื่อพ้นวันเข้าพักและลูกค้ายังไม่ check-in</p></template><div class="modal-actions"><button type="button" class="btn outline" :disabled="busy" @click="modal=''">กลับ</button><button class="btn primary" :disabled="busy">{{ busy?'กำลังบันทึก…':modal==='payment'&&payment.payment_method!=='cash'?'ส่งหลักฐาน':'ยืนยัน' }}</button></div></form></AppModal></section></template>
